export function SaleWorkspace() {
  const [products, setProducts] = useState([]), [cart, setCart] = useState([]), [selected, setSelected] = useState(''), [quantity, setQuantity] = useState('1'), [price, setPrice] = useState(''), [notes, setNotes] = useState(''), [error, setError] = useState(''), [saved, setSaved] = useState('')
  const load = async () => { try { setProducts(await api('/api/products')); setError('') } catch (e) { setError(e.message) } }
  useEffect(() => { load() }, [])
  const product = products.find(item => String(item.id) === String(selected))
  const add = event => { event.preventDefault(); if (!product) return; const amount = Number(quantity); if (!amount || amount <= 0) return; const unitPrice = Number(price || (Number(product.sale_price_cents || 0) / 100)); setCart(current => { const found = current.find(item => item.productId === product.id); if (found) return current.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + amount, unitPrice } : item); return [...current, { productId: product.id, name: product.name, basePrice: Number(product.sale_price_cents || 0) / 100, quantity: amount, unitPrice }] }); setQuantity('1'); setPrice('') }
  const total = cart.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0), baseTotal = cart.reduce((sum, item) => sum + item.quantity * item.basePrice, 0), discount = Math.max(0, baseTotal - total)
  const finish = async event => { event.preventDefault(); try { await api('/api/sales', { method: 'POST', body: JSON.stringify({ items: cart.map(item => ({ productId: item.productId, quantity: item.quantity, unitPrice: item.unitPrice })), notes }) }); setCart([]); setNotes(''); setSaved('Venda registrada, estoque atualizado e entrada lançada no financeiro.'); await load() } catch (e) { setError(e.message); setSaved('') } }
  return <><section className="page-head"><div><p className="eyebrow">COMERCIAL</p><h1>Nova venda</h1><p className="muted">Escolha os produtos, aplique descontos e registre a saída do estoque.</p></div><ShoppingCart size={25} color="#1f9d86" /></section>{error && <div className="api-error"><AlertTriangle size={18} />{error}</div>}{saved && <div className="success-notice"><CheckCircle2 size={18} />{saved}</div>}<section className="sale-layout"><form className="panel sale-picker" onSubmit={add}><div className="form-title"><span className="form-title-icon"><ShoppingCart size={20} /></span><div><h2>Adicionar produto</h2><p>O preço final determina automaticamente o desconto.</p></div></div><Field label="Produto"><select value={selected} onChange={event => { const next = event.target.value; setSelected(next); const item = products.find(productItem => String(productItem.id) === next); setPrice(item ? String(Number(item.sale_price_cents || 0) / 100) : '')} } required><option value="">Selecione um produto</option>{products.map(item => <option key={item.id} value={item.id}>{item.name} · saldo {item.quantity}</option>)}</select></Field><div className="sale-form-grid"><Field label="Quantidade"><input type="number" min="0.001" step="0.001" value={quantity} onChange={event => setQuantity(event.target.value)} /></Field><Field label="Preço final unitário"><input type="number" min="0.01" step="0.01" value={price} onChange={event => setPrice(event.target.value)} placeholder="Preço cadastrado" /></Field></div><button className="primary" disabled={!product}><Plus size={16} />Adicionar à venda</button></form><form className="panel sale-cart" onSubmit={finish}><div className="panel-head"><div><h2>Itens da venda</h2><p>{cart.length} produto(s) selecionado(s)</p></div></div>{cart.length ? <div className="sale-items">{cart.map(item => <div className="sale-item" key={item.productId}><div><b>{item.name}</b><small>Preço-base: {money(item.basePrice * 100)}</small></div><input type="number" min="0.001" step="0.001" value={item.quantity} onChange={event => setCart(current => current.map(row => row.productId === item.productId ? { ...row, quantity: Number(event.target.value) } : row))} /><input type="number" min="0.01" step="0.01" value={item.unitPrice} onChange={event => setCart(current => current.map(row => row.productId === item.productId ? { ...row, unitPrice: Number(event.target.value) } : row))} /><span>{item.basePrice ? `${Math.max(0, ((item.basePrice - item.unitPrice) / item.basePrice) * 100).toFixed(1)}%` : '—'}</span><b>{money(item.quantity * item.unitPrice * 100)}</b><button type="button" className="icon-button" onClick={() => setCart(current => current.filter(row => row.productId !== item.productId))}><X size={15} /></button></div>)}</div> : <Empty>Nenhum produto adicionado.</Empty>}<div className="sale-summary"><label><span>Observação</span><textarea value={notes} onChange={event => setNotes(event.target.value)} rows="2" placeholder="Cliente, forma de pagamento ou observação" /></label><div><span>Desconto calculado</span><b>{money(discount * 100)}</b><span>Total da venda</span><strong>{money(total * 100)}</strong></div></div><button className="primary" disabled={!cart.length}><Save size={16} />Finalizar venda</button></form></section></>
}


